import React, { Component } from 'react';
import Particles, { initParticlesEngine } from "@tsparticles/react";
import { loadSlim } from "@tsparticles/slim";
import * as faceapi from 'face-api.js';
import Navigation from './components/Navigation/Navigation.js';
import Signin from './components/SignIn/Signin.js';
import Register from './components/Register/Register.js';
import FaceRecognition from './components/FaceRecognition/FaceRecognition.js';
import Logo from './components/Logo/Logo.js';
import ImageLinkForm from './components/ImageLinkForm/ImageLinkForm.js';
import Rank from './components/Rank/Rank.js';
import './App.css';

const particleOptions = {
  particles: {
    number: {
      value: 50,
      density: {
        enable: true,
        area: 800
      }
    }
  }
};

class App extends Component {
  constructor() {
    super();
    this.state = {
      input: '',
      imageUrl: '',
      box: {},
      route: 'signin',
      isSignedIn: false,
      init: false,
      modelsLoaded: false,
      detecting: false
    };
  }

  componentDidMount() {
    // Init particles
    initParticlesEngine(async (engine) => {
      await loadSlim(engine);
    }).then(() => {
      this.setState({ init: true });
    });

    // Load face detection model
    faceapi.nets.tinyFaceDetector.loadFromUri('/facerecognitionbrain/models')
      .then(() => {
        console.log('Face detection model loaded!');
        this.setState({ modelsLoaded: true });
      })
      .catch(err => console.log('Model load error:', err));
  }

  detectFace = async () => {
    const image = document.getElementById('inputimage');
    if (!image || !this.state.modelsLoaded) return;

    this.setState({ detecting: true });

    try {
      const detection = await faceapi.detectSingleFace(
        image,
        new faceapi.TinyFaceDetectorOptions()
      );

      if (detection) {
        const displaySize = { width: image.width, height: image.height };
        const resizedDetection = faceapi.resizeResults(detection, displaySize);
        const box = resizedDetection.box;
        this.setState({
          box: {
            leftCol: box.x,
            topRow: box.y,
            rightCol: image.width - (box.x + box.width),
            bottomRow: image.height - (box.y + box.height)
          },
          detecting: false
        });
      } else {
        console.log('No face detected');
        this.setState({ box: {}, detecting: false });
      }
    } catch (err) {
      console.log('Detection error:', err);
      this.setState({ detecting: false });
    }
  }

  onInputChange = (event) => {
    this.setState({ input: event.target.value });
  }

  // Detect from URL
  onButtononSubmit = () => {
    if (!this.state.input) return;
    this.setState({ imageUrl: this.state.input, box: {} });
  }

  // Detect from local file
  onFileChange = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      this.setState({ imageUrl: reader.result, box: {} });
    };
    reader.readAsDataURL(file);
  }

  // Called when <img> finishes loading — run detection
  onImageLoaded = () => {
    this.detectFace();
  }

  onRouteChange = (route) => {
    if (route === 'signout') {
      this.setState({ isSignedIn: false });
    } else if (route === 'home') {
      this.setState({ isSignedIn: true });
    }
    this.setState({ route: route });
  }

  render() {
    const { isSignedIn, imageUrl, route, box, init, detecting } = this.state;
    return (
      <div className="App">
        {init && <Particles id="tsparticles" className='particles' options={particleOptions} />}
        <Navigation isSignedIn={isSignedIn} onRouteChange={this.onRouteChange} />
        {route === 'home'
          ? <div>
              <Logo />
              <Rank />
              <ImageLinkForm
                onInputChange={this.onInputChange}
                onButtononSubmit={this.onButtononSubmit}
                onFileChange={this.onFileChange}
              />
              {detecting && <p className='white f4'>Detecting face...</p>}
              <FaceRecognition box={box} imageUrl={imageUrl} onImageLoaded={this.onImageLoaded} />
            </div>
          : (
              this.state.route === 'signin'
              ? <Signin onRouteChange={this.onRouteChange} />
              : <Register onRouteChange={this.onRouteChange} />
            )
        }
      </div>
    );
  }
}

export default App;
